// GENERATED by `./gradlew generateMutants` — do not edit by hand; edit the catalog.
//
// Mutant min-accessories-strict (must-kill)
//
// Compiles the real :core sources with Leaves.kt REPLACED by the modified copy under
// src/main, then runs a test suite against the result. A good suite KILLS this mutant —
// some test fails here.

plugins {
    kotlin("jvm")
}

// Which suite runs against the mutant: "learner", or any test source dir given as a path
// relative to this build's root — set with -PmutantTests=<learner|path>. The default below
// is baked in per catalog at generation time, because -PmutantTests is global to the build
// and a build with two catalogs needs two different answers.
val suite: String = when (val selected = providers.gradleProperty("mutantTests").getOrElse("learner")) {
    "learner" -> "exercises/write-tests/src/test/kotlin"
    else -> selected
}

kotlin {
    jvmToolchain(21)

    sourceSets.named("main") {
        kotlin.srcDir(rootDir.resolve("core/src/main/kotlin"))
        
        kotlin.exclude("**/Leaves.kt")
    }
    sourceSets.named("test") {
        kotlin.srcDir(rootDir.resolve(suite))
    }
}

repositories {
    mavenCentral()
}

dependencies {
    testImplementation(kotlin("test"))
}

tasks.test {
    useJUnitPlatform()
    // verifyMutants reads the XML results, so a killed mutant must not break the build.
    ignoreFailures = true
}

// A compile failure must leave NO results behind. `test` never starts when compilation fails, so
// the previous run's XML would still be sitting there and the report would print that score for a
// suite that no longer builds — measured: a clean "1/4 killed" for a suite with a type error in it.
// Clearing as compilation STARTS is what makes the report's "did not compile" branch mean it.
val resultsDir = layout.buildDirectory.dir("test-results/test")
listOf("compileKotlin", "compileTestKotlin").forEach { stage ->
    tasks.named(stage) { doFirst { resultsDir.get().asFile.deleteRecursively() } }
}
